def transforms(shape):
    res=set()
    pts=np.array(list(shape))
    for k in range(4):
        p=pts.copy()
        for _ in range(k): p=np.stack([p[:,1],-p[:,0]],axis=1)
        for refl in [False,True]:
            q=p.copy(); q[:,1]=(-q[:,1] if refl else q[:,1]); q=q-q.min(axis=0)
            res.add(frozenset(map(tuple,q.tolist())))
    return res

def match_union(grid, shape, bg, orientations=True):
    h,w=grid.shape; result=set(); occ=[]
    shapes=transforms(shape) if orientations else {frozenset((r-rmin,c-cmin) for r,c in shape) for rmin,cmin in [(min(r for r,c in shape),min(c for r,c in shape))]}
    for sh in shapes:
        hh=max(r for r,c in sh)+1; ww=max(c for r,c in sh)+1
        for r in range(h-hh+1):
          for c in range(w-ww+1):
            coords={(r+a,c+b) for a,b in sh}
            if all(grid[x,y]==bg for x,y in coords):
                result |= coords; occ.append((sh,r,c))
    return result,occ
